public static double trimMean(int[] arr) {
    Arrays.sort(arr);
    int size = arr.length;
    int trimSize = size * 0.05;
    int start = trimSize;
    int end = size - trimSize;

    int sum = 0;
    for (int i = start; i <= end; i++) {
