public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of elements in the array
    int totalSum = Arrays.stream(nums).sum();
    int n = nums.length;

    // Iterate over possible split points
    for (int i = 0; i < n - 1; i++) {
        int leftSum = totalSum - nums[i];
        int rightSum = totalSum;
        int target = leftSum * 2;
        // If the target is greater than leftSum, skip split
        if (target > leftSum) continue;
        // Starting left pointer from i + 1
        for (int l = i + 1; l < n; l++) {
            rightSum -= nums[l];
            // Check if the right sum equals target
            if (rightSum == target) {
                return true;
            }
        }
        // If no split found, reset right sum and continue
        rightSum = totalSum;
    }
    // If still no split found
    return false;
}

