public boolean hasAllCodes(String s, int k) {
    int requiredLength = (int) Math.pow(2, k);
    if (s.length() < requiredLength) {
        return false;
    }
    Set<String> seenStrings = new HashSet<>();

    // Check every substring of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        if (!seenStrings.add(substring)) {
            return false;
        }
    }

    return true;
}

