public int findMinFibonacciNumbers(int k) {
    int[] fib = {0, 1};
    while (fib[fib.length - 1] < k) {
        fib[fib.length] = fib[fib.length - 1] + fib[fib.length - 2];
    }
    int count = 0;
    for (int i = fib.length - 1; i >= 0 && k > 0; i--) {
        while (k >= fib[i]) {
            count++;
            k -= fib[i];
        }
    }
    return count;
}

