public int kthFactor(int n, int k) {
        ArrayList<Long> divisors = new ArrayList<>();

        // Find all divisors of n
        for (long i = 1; i <= n; i++) {
            if (n % i == 0) {
                divisors.add(i);
            }
        }

        // Sort the divisors in ascending order
        Collections.sort(divisors);

        // Print the k-th smallest divisor or -1 if there are fewer than k divisors
        if (divisors.size() < k) {
            return -1;
        } else {
            return (int) divisors.get(k - 1);
        }
    }

