public static int findSmallestInteger(int n) {
    String nStr = String.valueOf(n);
    int[] digits = new int[nStr.length()];
    for (int i = 0; i < nStr.length(); i++) {
        digits[i] = nStr.charAt(i) - '0';
    }

    boolean swapped = false;
    for (int i = nStr.length() - 1; i >= 0; i--) {
        for (int j = i - 1; j >= 0; j--) {
            if (digits[i] < digits[j]) {
                // Swap digits
                int temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;

                // Mark that a swap has been made
                swapped = true;
                break;
            }
        }
        if (swapped) {
            // Convert the array of digits back to a number
            int smallestNumber = 0;
            for (int digit : digits) {
                smallestNumber = smallestNumber * 10 + digit;
            }
            return smallestNumber;
        }
    }

    // If no further swaps are possible
    return -1;
}

