public static int findSmallestInteger(int n) {
    int temp = n;
    while (temp > 0) {
        temp /= 10;
    }
    int x = 0;
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }
    Collections.sort(digits);
    for (int digit : digits) {
        if (digit > temp) {
            temp = digit;
            break;
        }
    }
    for (int i = 0; i < digits.size(); i++) {
        if (digits.get(i) > temp)
            break;
        x = x * 10 + digits.get(i);
    }
    if (x == n) return -1;
    return x;
